from .errors import TypeMismatchError


def type_of(v: object) -> str:
    """Return the type name of a value."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    return "NULL"


def is_numeric(v: object) -> bool:
    """Check if a value is numeric (INT or FLOAT, not BOOL)."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND."""
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    if a is True:
        return b
    if b is True:
        return a
    return None


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR."""
    if a is True or b is True:
        return True
    if a is False and b is False:
        return False
    if a is False:
        return b
    if b is False:
        return a
    return None


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT."""
    if a is True:
        return False
    if a is False:
        return True
    return None


def compare_eq(a: object, b: object) -> bool | None:
    """Three-valued equality comparison."""
    if a is None or b is None:
        return None
    ta, tb = type_of(a), type_of(b)
    if ta == "BOOL" or tb == "BOOL":
        if ta != tb:
            raise TypeMismatchError(f"Cannot compare {ta} and {tb}")
        return a == b
    if ta in ("INT", "FLOAT") and tb in ("INT", "FLOAT"):
        return a == b
    if ta == "TEXT" and tb == "TEXT":
        return a == b
    if ta != tb:
        raise TypeMismatchError(f"Cannot compare {ta} and {tb}")
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """Three-valued less-than comparison."""
    if a is None or b is None:
        return None
    ta, tb = type_of(a), type_of(b)
    if ta == "BOOL" or tb == "BOOL":
        if ta != tb:
            raise TypeMismatchError(f"Cannot compare {ta} and {tb}")
        return a < b
    if ta in ("INT", "FLOAT") and tb in ("INT", "FLOAT"):
        return a < b
    if ta == "TEXT" and tb == "TEXT":
        return a < b
    raise TypeMismatchError(f"Cannot compare {ta} and {tb}")


def arith(op: str, a: object, b: object) -> object:
    """Arithmetic operation."""
    if a is None or b is None:
        return None
    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(
            f"Cannot perform {op} on {type_of(a)} and {type_of(b)}"
        )
    if op == "+":
        return a + b if not isinstance(a, float) and not isinstance(b, float) else float(a) + float(b)
    if op == "-":
        return a - b if not isinstance(a, float) and not isinstance(b, float) else float(a) - float(b)
    if op == "*":
        return a * b if not isinstance(a, float) and not isinstance(b, float) else float(a) * float(b)
    if op == "/":
        if a == 0 or b == 0:
            return None
        return float(a) / float(b)
    if op == "%":
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeMismatchError(f"Modulo requires INT operands")
        if b == 0:
            return None
        return a % b
    raise ValueError(f"Unknown operator: {op}")


def negate(a: object) -> object:
    """Unary negation."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"Cannot negate {type_of(a)}")
    return -a

import dataclasses
from .errors import SchemaError
from .value import type_of


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


class Table:
    def __init__(
        self, name: str, columns: list[Column], rows: list[list[object]]
    ) -> None:
        if not columns:
            raise SchemaError("Table must have at least one column")
        if len(set(c.name for c in columns)) != len(columns):
            raise SchemaError("Column names must be unique")
        for col in columns:
            if col.type not in ("INT", "FLOAT", "TEXT", "BOOL"):
                raise SchemaError(f"Invalid type: {col.type}")
        for row in rows:
            if len(row) != len(columns):
                raise SchemaError(
                    f"Row length {len(row)} does not match column count {len(columns)}"
                )
            for i, cell in enumerate(row):
                if cell is None:
                    continue
                col_type = columns[i].type
                val_type = type_of(cell)
                if col_type == "INT":
                    if not isinstance(cell, int) or isinstance(cell, bool):
                        raise SchemaError(
                            f"Column {columns[i].name} expects INT, got {val_type}"
                        )
                elif col_type == "FLOAT":
                    if isinstance(cell, bool) or not isinstance(cell, (int, float)):
                        raise SchemaError(
                            f"Column {columns[i].name} expects FLOAT, got {val_type}"
                        )
                    if isinstance(cell, int) and not isinstance(cell, bool):
                        row[i] = float(cell)
                elif col_type == "TEXT":
                    if not isinstance(cell, str):
                        raise SchemaError(
                            f"Column {columns[i].name} expects TEXT, got {val_type}"
                        )
                elif col_type == "BOOL":
                    if not isinstance(cell, bool):
                        raise SchemaError(
                            f"Column {columns[i].name} expects BOOL, got {val_type}"
                        )
        self._name = name
        self._columns = columns
        self._rows = rows

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, col in enumerate(self._columns):
            if col.name == name:
                return i
        raise SchemaError(f"Column '{name}' not found in table '{self._name}'")

from .errors import LexError


KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON", "WHERE",
    "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC", "LIMIT", "OFFSET", "AS",
    "AND", "OR", "NOT", "IS", "NULL", "TRUE", "FALSE"
}


class Token:
    def __init__(
        self, type: str, value: object, offset: int
    ) -> None:
        self.type = type
        self.value = value
        self.offset = offset

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value!r}, {self.offset})"


class Lexer:
    def __init__(self, query: str) -> None:
        self.query = query
        self.pos = 0
        self.tokens: list[Token] = []

    def lex(self) -> list[Token]:
        while self.pos < len(self.query):
            self._skip_whitespace_and_comments()
            if self.pos >= len(self.query):
                break
            ch = self.query[self.pos]
            if ch == "'":
                self._read_string()
            elif ch.isdigit() or (ch == "." and
                                   self.pos + 1 < len(self.query) and
                                   self.query[self.pos + 1].isdigit()):
                self._read_number()
            elif ch.isalpha() or ch == "_":
                self._read_ident()
            elif ch in "(),.":
                self.tokens.append(Token(ch, ch, self.pos))
                self.pos += 1
            elif ch == "=":
                self.tokens.append(Token("=", "=", self.pos))
                self.pos += 1
            elif ch == "<":
                if self.pos + 1 < len(self.query) and self.query[self.pos + 1] == ">":
                    self.tokens.append(Token("<>", "<>", self.pos))
                    self.pos += 2
                elif self.pos + 1 < len(self.query) and self.query[self.pos + 1] == "=":
                    self.tokens.append(Token("<=", "<=", self.pos))
                    self.pos += 2
                else:
                    self.tokens.append(Token("<", "<", self.pos))
                    self.pos += 1
            elif ch == ">":
                if self.pos + 1 < len(self.query) and self.query[self.pos + 1] == "=":
                    self.tokens.append(Token(">=", ">=", self.pos))
                    self.pos += 2
                else:
                    self.tokens.append(Token(">", ">", self.pos))
                    self.pos += 1
            elif ch in "+-*/%":
                self.tokens.append(Token(ch, ch, self.pos))
                self.pos += 1
            else:
                raise LexError(f"Unexpected character: {ch}", self.pos)
        return self.tokens

    def _skip_whitespace_and_comments(self) -> None:
        while self.pos < len(self.query):
            if self.query[self.pos].isspace():
                self.pos += 1
            elif self.pos + 1 < len(self.query) and self.query[self.pos:self.pos+2] == "--":
                while self.pos < len(self.query) and self.query[self.pos] != "\n":
                    self.pos += 1
            else:
                break

    def _read_string(self) -> None:
        start = self.pos
        self.pos += 1
        value = ""
        while self.pos < len(self.query):
            if self.query[self.pos] == "'":
                if self.pos + 1 < len(self.query) and self.query[self.pos + 1] == "'":
                    value += "'"
                    self.pos += 2
                else:
                    self.pos += 1
                    self.tokens.append(Token("TEXT", value, start))
                    return
            else:
                value += self.query[self.pos]
                self.pos += 1
        raise LexError("Unterminated string", start)

    def _read_number(self) -> None:
        start = self.pos
        value = ""
        has_dot = False
        while self.pos < len(self.query):
            ch = self.query[self.pos]
            if ch.isdigit():
                value += ch
                self.pos += 1
            elif ch == "." and not has_dot:
                has_dot = True
                value += ch
                self.pos += 1
            elif ch in "eE":
                value += ch
                self.pos += 1
                if self.pos < len(self.query) and self.query[self.pos] in "+-":
                    value += self.query[self.pos]
                    self.pos += 1
            else:
                break
        if has_dot or "e" in value.lower():
            self.tokens.append(Token("FLOAT", float(value), start))
        else:
            self.tokens.append(Token("INT", int(value), start))

    def _read_ident(self) -> None:
        start = self.pos
        value = ""
        while self.pos < len(self.query):
            ch = self.query[self.pos]
            if ch.isalnum() or ch == "_":
                value += ch
                self.pos += 1
            else:
                break
        upper_value = value.upper()
        if upper_value in KEYWORDS:
            self.tokens.append(Token(upper_value, value, start))
        else:
            self.tokens.append(Token("IDENT", value, start))

