import dataclasses


@dataclasses.dataclass
class Query:
    distinct: bool
    select_items: list["SelectItem"]
    from_table: str | None
    join: "Join | None"
    where_expr: "Expr | None"
    group_by: list["Expr"]
    having_expr: "Expr | None"
    order_by: list[tuple["Expr", str]]
    limit: int | None
    offset: int | None


@dataclasses.dataclass
class SelectItem:
    expr: "Expr | None"
    alias: str | None
    star_table: str | None


@dataclasses.dataclass
class Join:
    type: str
    table: str
    on_expr: "Expr"


@dataclasses.dataclass
class Expr:
    type: str
    value: object = None
    left: "Expr | None" = None
    right: "Expr | None" = None
    args: list["Expr"] | None = None
    col_table: str | None = None
    col_name: str | None = None


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> Query:
        distinct = False
        if self._match("SELECT"):
            if self._match("DISTINCT"):
                distinct = True
            select_items = self._parse_select_list()
        else:
            raise ParseError("Expected SELECT", self._offset())

        from_table = None
        join = None
        if self._match("FROM"):
            from_table = self._expect("IDENT").value
            if self._match("INNER"):
                self._expect("JOIN")
                join_table = self._expect("IDENT").value
                self._expect("ON")
                on_expr = self._parse_or_expr()
                join = Join(type="INNER", table=join_table, on_expr=on_expr)
            elif self._match("LEFT"):
                self._expect("JOIN")
                join_table = self._expect("IDENT").value
                self._expect("ON")
                on_expr = self._parse_or_expr()
                join = Join(type="LEFT", table=join_table, on_expr=on_expr)

        where_expr = None
        if self._match("WHERE"):
            where_expr = self._parse_or_expr()

        group_by = []
        if self._match("GROUP"):
            self._expect("BY")
            group_by.append(self._parse_or_expr())
            while self._match(","):
                group_by.append(self._parse_or_expr())

        having_expr = None
        if self._match("HAVING"):
            having_expr = self._parse_or_expr()

        order_by = []
        if self._match("ORDER"):
            self._expect("BY")
            order_by.append((self._parse_or_expr(), "ASC"))
            if self._check("ASC"):
                self.pos += 1
            elif self._check("DESC"):
                self.pos += 1
                order_by[-1] = (order_by[-1][0], "DESC")
            while self._match(","):
                order_by.append((self._parse_or_expr(), "ASC"))
                if self._check("ASC"):
                    self.pos += 1
                elif self._check("DESC"):
                    self.pos += 1
                    order_by[-1] = (order_by[-1][0], "DESC")

        limit = None
        if self._match("LIMIT"):
            limit = self._expect("INT").value

        offset_val = None
        if self._match("OFFSET"):
            offset_val = self._expect("INT").value

        return Query(
            distinct=distinct,
            select_items=select_items,
            from_table=from_table,
            join=join,
            where_expr=where_expr,
            group_by=group_by,
            having_expr=having_expr,
            order_by=order_by,
            limit=limit,
            offset=offset_val
        )

    def _parse_select_list(self) -> list[SelectItem]:
        items = []
        if self._check("*"):
            self.pos += 1
            items.append(SelectItem(expr=None, alias=None, star_table=None))
        else:
            items.append(self._parse_select_item())
            while self._match(","):
                items.append(self._parse_select_item())
        return items

    def _parse_select_item(self) -> SelectItem:
        if self._check("IDENT"):
            ident_tok = self._expect("IDENT")
            if self._match("."):
                if self._check("*"):
                    self.pos += 1
                    return SelectItem(expr=None, alias=None, star_table=ident_tok.value)
                else:
                    col = self._expect("IDENT")
                    expr = Expr(
                        type="col",
                        col_table=ident_tok.value,
                        col_name=col.value
                    )
            else:
                expr = Expr(type="col", col_table=None, col_name=ident_tok.value)
        else:
            expr = self._parse_or_expr()

        alias = None
        if self._match("AS"):
            alias = self._expect("IDENT").value
        elif self._check("IDENT") and not self._is_keyword(self.tokens[self.pos].value.upper()):
            alias = self._expect("IDENT").value

        return SelectItem(expr=expr, alias=alias, star_table=None)

    def _parse_or_expr(self) -> Expr:
        left = self._parse_and_expr()
        while self._match("OR"):
            right = self._parse_and_expr()
            left = Expr(type="or", left=left, right=right)
        return left

    def _parse_and_expr(self) -> Expr:
        left = self._parse_not_expr()
        while self._match("AND"):
            right = self._parse_not_expr()
            left = Expr(type="and", left=left, right=right)
        return left

    def _parse_not_expr(self) -> Expr:
        if self._match("NOT"):
            expr = self._parse_not_expr()
            return Expr(type="not", left=expr)
        return self._parse_predicate()

    def _parse_predicate(self) -> Expr:
        left = self._parse_additive()
        if self._match("IS"):
            if self._match("NOT"):
                self._expect("NULL")
                return Expr(type="is_not_null", left=left)
            else:
                self._expect("NULL")
                return Expr(type="is_null", left=left)
        elif self._check("=") or self._check("<>") or self._check("<") or \
             self._check("<=") or self._check(">") or self._check(">="):
            op = self.tokens[self.pos].value
            self.pos += 1
            right = self._parse_additive()
            return Expr(type="cmp", value=op, left=left, right=right)
        return left

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while self._check("+") or self._check("-"):
            op = self.tokens[self.pos].value
            self.pos += 1
            right = self._parse_multiplicative()
            left = Expr(type="arith", value=op, left=left, right=right)
        return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while self._check("*") or self._check("/") or self._check("%"):
            op = self.tokens[self.pos].value
            self.pos += 1
            right = self._parse_unary()
            left = Expr(type="arith", value=op, left=left, right=right)
        return left

    def _parse_unary(self) -> Expr:
        if self._match("-"):
            expr = self._parse_unary()
            return Expr(type="neg", left=expr)
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        if self._check("INT"):
            tok = self._expect("INT")
            return Expr(type="lit", value=tok.value)
        if self._check("FLOAT"):
            tok = self._expect("FLOAT")
            return Expr(type="lit", value=tok.value)
        if self._check("TEXT"):
            tok = self._expect("TEXT")
            return Expr(type="lit", value=tok.value)
        if self._match("TRUE"):
            return Expr(type="lit", value=True)
        if self._match("FALSE"):
            return Expr(type="lit", value=False)
        if self._match("NULL"):
            return Expr(type="lit", value=None)
        if self._match("("):
            expr = self._parse_or_expr()
            self._expect(")")
            return expr
        if self._check("IDENT"):
            ident = self._expect("IDENT")
            if self._match("."):
                col = self._expect("IDENT")
                return Expr(type="col", col_table=ident.value, col_name=col.value)
            elif self._match("("):
                args = []
                if not self._check(")"):
                    if self._match("*"):
                        args.append(Expr(type="lit", value="*"))
                    else:
                        args.append(self._parse_or_expr())
                        while self._match(","):
                            args.append(self._parse_or_expr())
                self._expect(")")
                return Expr(type="call", value=ident.value, args=args)
            else:
                return Expr(type="col", col_table=None, col_name=ident.value)
        raise ParseError(f"Unexpected token", self._offset())

    def _match(self, *types: str) -> bool:
        for t in types:
            if self._check(t):
                self.pos += 1
                return True
        return False

    def _check(self, type: str) -> bool:
        if self.pos >= len(self.tokens):
            return False
        return self.tokens[self.pos].type == type

    def _expect(self, type: str) -> Token:
        if not self._check(type):
            raise ParseError(f"Expected {type}", self._offset())
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _offset(self) -> int:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos].offset
        return len(self.tokens) - 1 if self.tokens else 0

    def _is_keyword(self, word: str) -> bool:
        return word in {
            "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON",
            "WHERE", "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC",
            "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
            "TRUE", "FALSE"
        }

from .parser import Expr
from .errors import TypeMismatchError, UnknownFunctionError, ArityError, AggregateError
from .value import (
    compare_eq, compare_lt, arith, negate, type_of, and_, or_, not_,
    is_numeric
)


def evaluate(expr: Expr, row: dict[str, object], is_aggregate_context: bool = False) -> object:
    """Evaluate an expression in a row context."""
    if expr.type == "lit":
        return expr.value
    if expr.type == "col":
        if expr.col_name not in row:
            raise KeyError(f"Column '{expr.col_name}' not found")
        return row[expr.col_name]
    if expr.type == "cmp":
        left = evaluate(expr.left, row, is_aggregate_context)
        right = evaluate(expr.right, row, is_aggregate_context)
        op = expr.value
        if op == "=":
            return compare_eq(left, right)
        if op == "<>":
            return not_(compare_eq(left, right))
        if op == "<":
            return compare_lt(left, right)
        if op == "<=":
            left_eq = compare_eq(left, right)
            left_lt = compare_lt(left, right)
            if left_eq is None or left_lt is None:
                return None if left_eq is None and left_lt is None else (left_eq or left_lt)
            return left_eq or left_lt
        if op == ">":
            return compare_lt(right, left)
        if op == ">=":
            right_eq = compare_eq(left, right)
            right_lt = compare_lt(right, left)
            if right_eq is None or right_lt is None:
                return None if right_eq is None and right_lt is None else (right_eq or right_lt)
            return right_eq or right_lt
    if expr.type == "arith":
        left = evaluate(expr.left, row, is_aggregate_context)
        right = evaluate(expr.right, row, is_aggregate_context)
        return arith(expr.value, left, right)
    if expr.type == "neg":
        val = evaluate(expr.left, row, is_aggregate_context)
        return negate(val)
    if expr.type == "and":
        left = evaluate(expr.left, row, is_aggregate_context)
        right = evaluate(expr.right, row, is_aggregate_context)
        return and_(left, right)
    if expr.type == "or":
        left = evaluate(expr.left, row, is_aggregate_context)
        right = evaluate(expr.right, row, is_aggregate_context)
        return or_(left, right)
    if expr.type == "not":
        val = evaluate(expr.left, row, is_aggregate_context)
        return not_(val)
    if expr.type == "is_null":
        val = evaluate(expr.left, row, is_aggregate_context)
        return val is None
    if expr.type == "is_not_null":
        val = evaluate(expr.left, row, is_aggregate_context)
        return val is not None
    if expr.type == "call":
        if is_aggregate_context:
            raise AggregateError(f"Cannot use function {expr.value} in aggregate context")
        return evaluate_call(expr.value, expr.args or [], row)
    raise ValueError(f"Unknown expression type: {expr.type}")


def evaluate_call(func_name: str, args: list[Expr], row: dict[str, object]) -> object:
    """Evaluate a function call."""
    func_name_lower = func_name.lower()
    if func_name_lower == "concat":
        if len(args) < 2:
            raise ArityError(
                f"concat() takes at least 2 arguments, got {len(args)}", func_name, 2
            )
        result = ""
        for arg in args:
            val = evaluate(arg, row)
            if val is None:
                return None
            if not isinstance(val, str):
                raise TypeMismatchError(f"concat() requires TEXT arguments")
            result += val
        return result
    if func_name_lower == "upper":
        if len(args) != 1:
            raise ArityError(f"upper() takes 1 argument, got {len(args)}", func_name, 1)
        val = evaluate(args[0], row)
        if val is None:
            return None
        if not isinstance(val, str):
            raise TypeMismatchError(f"upper() requires TEXT argument")
        return val.upper()
    if func_name_lower == "lower":
        if len(args) != 1:
            raise ArityError(f"lower() takes 1 argument, got {len(args)}", func_name, 1)
        val = evaluate(args[0], row)
        if val is None:
            return None
        if not isinstance(val, str):
            raise TypeMismatchError(f"lower() requires TEXT argument")
        return val.lower()
    if func_name_lower == "length":
        if len(args) != 1:
            raise ArityError(f"length() takes 1 argument, got {len(args)}", func_name, 1)
        val = evaluate(args[0], row)
        if val is None:
            return None
        if not isinstance(val, str):
            raise TypeMismatchError(f"length() requires TEXT argument")
        return len(val)
    if func_name_lower == "abs":
        if len(args) != 1:
            raise ArityError(f"abs() takes 1 argument, got {len(args)}", func_name, 1)
        val = evaluate(args[0], row)
        if val is None:
            return None
        if not is_numeric(val):
            raise TypeMismatchError(f"abs() requires numeric argument")
        return abs(val)
    if func_name_lower == "coalesce":
        if len(args) < 1:
            raise ArityError(f"coalesce() takes at least 1 argument, got {len(args)}", func_name, 1)
        for arg in args:
            val = evaluate(arg, row)
            if val is not None:
                return val
        return None
    raise UnknownFunctionError(f"Unknown function: {func_name}")


def is_aggregate_expr(expr: Expr) -> bool:
    """Check if an expression contains an aggregate function."""
    if expr is None:
        return False
    if expr.type == "call":
        func_name = expr.value.lower()
        return func_name in ("count", "sum", "avg", "min", "max")
    if expr.left and is_aggregate_expr(expr.left):
        return True
    if expr.right and is_aggregate_expr(expr.right):
        return True
    if expr.args:
        return any(is_aggregate_expr(arg) for arg in expr.args)
    return False


def expr_to_string(expr: Expr) -> str:
    """Convert an expression to string for column naming."""
    if expr.type == "lit":
        return str(expr.value)
    if expr.type == "col":
        if expr.col_table:
            return f"{expr.col_table}.{expr.col_name}"
        return expr.col_name
    if expr.type == "call":
        args_str = ", ".join(expr_to_string(arg) for arg in (expr.args or []))
        return f"{expr.value}({args_str})"
    if expr.type == "cmp":
        return f"{expr_to_string(expr.left)} {expr.value} {expr_to_string(expr.right)}"
    if expr.type == "arith":
        return f"{expr_to_string(expr.left)} {expr.value} {expr_to_string(expr.right)}"
    if expr.type == "neg":
        return f"-{expr_to_string(expr.left)}"
    if expr.type == "and":
        return f"{expr_to_string(expr.left)} AND {expr_to_string(expr.right)}"
    if expr.type == "or":
        return f"{expr_to_string(expr.left)} OR {expr_to_string(expr.right)}"
    if expr.type == "not":
        return f"NOT {expr_to_string(expr.left)}"
    if expr.type == "is_null":
        return f"{expr_to_string(expr.left)} IS NULL"
    if expr.type == "is_not_null":
        return f"{expr_to_string(expr.left)} IS NOT NULL"
    return str(expr)

from .parser import Expr
from .expr import evaluate, is_aggregate_expr
from .errors import ArityError, TypeMismatchError, AggregateError
from .value import type_of, is_numeric, compare_lt


class Aggregator:
    def __init__(self, expr: Expr, rows: list[dict[str, object]]) -> None:
        self.expr = expr
        self.rows = rows

    def compute(self) -> object:
        """Compute the aggregate value."""
        if self.expr.type != "call":
            raise AggregateError(f"Not an aggregate")
        func_name = self.expr.value.lower()
        args = self.expr.args or []

        if func_name == "count":
            if len(args) == 1 and args[0].type == "lit" and args[0].value == "*":
                return len(self.rows)
            if len(args) != 1:
                raise ArityError(f"count() takes 1 argument, got {len(args)}", "count", 1)
            count = 0
            for row in self.rows:
                val = evaluate(args[0], row)
                if val is not None:
                    count += 1
            return count

        if func_name == "sum":
            if len(args) != 1:
                raise ArityError(f"sum() takes 1 argument, got {len(args)}", "sum", 1)
            values = []
            for row in self.rows:
                val = evaluate(args[0], row)
                if val is not None:
                    if not is_numeric(val):
                        raise TypeMismatchError(f"sum() requires numeric values")
                    values.append(val)
            if not values:
                return None
            total = sum(values)
            has_float = any(isinstance(v, float) for v in values)
            return float(total) if has_float else total

        if func_name == "avg":
            if len(args) != 1:
                raise ArityError(f"avg() takes 1 argument, got {len(args)}", "avg", 1)
            values = []
            for row in self.rows:
                val = evaluate(args[0], row)
                if val is not None:
                    if not is_numeric(val):
                        raise TypeMismatchError(f"avg() requires numeric values")
                    values.append(val)
            if not values:
                return None
            return sum(values) / len(values)

        if func_name == "min":
            if len(args) != 1:
                raise ArityError(f"min() takes 1 argument, got {len(args)}", "min", 1)
            values = []
            for row in self.rows:
                val = evaluate(args[0], row)
                if val is not None:
                    values.append(val)
            if not values:
                return None
            if values and isinstance(values[0], bool):
                all_bool = all(isinstance(v, bool) for v in values)
                if not all_bool:
                    raise TypeMismatchError(f"Cannot mix BOOL with other types in min()")
                return min(values)
            first_type = type_of(values[0])
            for v in values[1:]:
                if type_of(v) != first_type and not (
                    first_type in ("INT", "FLOAT") and type_of(v) in ("INT", "FLOAT")
                ):
                    raise TypeMismatchError(f"Cannot mix types in min()")
            return min(values, key=lambda x: (x is None, x))

        if func_name == "max":
            if len(args) != 1:
                raise ArityError(f"max() takes 1 argument, got {len(args)}", "max", 1)
            values = []
            for row in self.rows:
                val = evaluate(args[0], row)
                if val is not None:
                    values.append(val)
            if not values:
                return None
            if values and isinstance(values[0], bool):
                all_bool = all(isinstance(v, bool) for v in values)
                if not all_bool:
                    raise TypeMismatchError(f"Cannot mix BOOL with other types in max()")
                return max(values)
            first_type = type_of(values[0])
            for v in values[1:]:
                if type_of(v) != first_type and not (
                    first_type in ("INT", "FLOAT") and type_of(v) in ("INT", "FLOAT")
                ):
                    raise TypeMismatchError(f"Cannot mix types in max()")
            return max(values, key=lambda x: (x is None, x))

        raise AggregateError(f"Unknown aggregate: {func_name}")

from .parser import Query, Expr
from .expr import is_aggregate_expr
import dataclasses


@dataclasses.dataclass
class Stage:
    name: str


@dataclasses.dataclass
class FromStage(Stage):
    table: str
    join_type: str | None = None
    join_table: str | None = None
    join_on_expr: Expr | None = None


@dataclasses.dataclass
class WhereStage(Stage):
    expr: Expr


@dataclasses.dataclass
class GroupByStage(Stage):
    exprs: list[Expr]


@dataclasses.dataclass
class HavingStage(Stage):
    expr: Expr


@dataclasses.dataclass
class SelectStage(Stage):
    distinct: bool
    items: list[tuple[Expr | None, str | None, str | None]]


@dataclasses.dataclass
class OrderByStage(Stage):
    items: list[tuple[Expr, str]]


@dataclasses.dataclass
class LimitOffsetStage(Stage):
    limit: int | None
    offset: int | None


Plan = list[Stage]


def plan(query: Query) -> Plan:
    """Create an execution plan from a query."""
    stages: Plan = []

    stages.append(FromStage(
        name="FROM",
        table=query.from_table or "",
        join_type=query.join.type if query.join else None,
        join_table=query.join.table if query.join else None,
        join_on_expr=query.join.on_expr if query.join else None
    ))

    if query.where_expr:
        stages.append(WhereStage(name="WHERE", expr=query.where_expr))

    if query.group_by:
        stages.append(GroupByStage(name="GROUP_BY", exprs=query.group_by))

    has_aggregate = any(
        is_aggregate_expr(item.expr)
        for item in query.select_items
        if item.expr
    ) or (query.having_expr and is_aggregate_expr(query.having_expr))

    if has_aggregate and not query.group_by:
        stages.append(GroupByStage(name="GROUP_BY", exprs=[]))

    if query.having_expr:
        stages.append(HavingStage(name="HAVING", expr=query.having_expr))

    select_items = []
    for item in query.select_items:
        select_items.append((item.expr, item.alias, item.star_table))

    stages.append(SelectStage(
        name="SELECT",
        distinct=query.distinct,
        items=select_items
    ))

    if query.distinct:
        stages.append(Stage(name="DISTINCT"))

    if query.order_by:
        stages.append(OrderByStage(name="ORDER_BY", items=query.order_by))

    if query.limit is not None or query.offset is not None:
        stages.append(LimitOffsetStage(
            name="LIMIT_OFFSET",
            limit=query.limit,
            offset=query.offset
        ))

    return stages

import dataclasses
from .planner import Plan, Stage, FromStage, WhereStage, GroupByStage, HavingStage, SelectStage, OrderByStage, LimitOffsetStage
from .schema import Table
from .expr import evaluate, expr_to_string, is_aggregate_expr
from .aggregate import Aggregator
from .value import compare_lt, type_of
from .errors import (
    TypeMismatchError, UnknownColumnError, AmbiguousColumnError,
    UnknownTableError, GroupingError
)


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    """Execute a query plan and return the result."""
    rows = []
    output_columns = []

    for stage in plan:
        if isinstance(stage, FromStage):
            rows = _execute_from(stage, tables)
        elif isinstance(stage, WhereStage):
            rows = _execute_where(stage, rows)
        elif isinstance(stage, GroupByStage):
            rows = _execute_group_by(stage, rows)
        elif isinstance(stage, HavingStage):
            rows = _execute_having(stage, rows)
        elif isinstance(stage, SelectStage):
            rows, output_columns = _execute_select(stage, rows, tables, plan)
        elif isinstance(stage, LimitOffsetStage):
            rows = _execute_limit_offset(stage, rows)
        elif isinstance(stage, OrderByStage):
            rows = _execute_order_by(stage, rows, output_columns, tables, plan)
        elif stage.name == "DISTINCT":
            rows = _execute_distinct(rows)

    return Result(columns=output_columns, rows=rows)


def _execute_from(stage: FromStage, tables: dict[str, Table]) -> list[dict[str, object]]:
    """Execute FROM clause."""
    if not stage.table:
        return []
    if stage.table not in tables:
        raise UnknownTableError(f"Table '{stage.table}' not found")

    left_table = tables[stage.table]
    rows = []
    for row_data in left_table.rows:
        row = {}
        for i, col in enumerate(left_table.columns):
            row[f"{stage.table}.{col.name}"] = row_data[i]
            row[col.name] = row_data[i]
        rows.append(row)

    if stage.join_type:
        if stage.join_table not in tables:
            raise UnknownTableError(f"Table '{stage.join_table}' not found")
        right_table = tables[stage.join_table]

        if stage.join_type == "INNER":
            rows = _execute_inner_join(rows, right_table, stage.join_table, stage.join_on_expr)
        elif stage.join_type == "LEFT":
            rows = _execute_left_join(rows, right_table, stage.join_table, stage.join_on_expr)

    return rows


def _execute_inner_join(
    left_rows: list[dict[str, object]], right_table: Table, right_name: str, on_expr: object
) -> list[dict[str, object]]:
    """Execute INNER JOIN."""
    result = []
    for left_row in left_rows:
        for right_row_data in right_table.rows:
            combined = left_row.copy()
            for i, col in enumerate(right_table.columns):
                combined[f"{right_name}.{col.name}"] = right_row_data[i]
                if col.name not in combined:
                    combined[col.name] = right_row_data[i]

            pred = evaluate(on_expr, combined)
            if pred is True:
                result.append(combined)
    return result


def _execute_left_join(
    left_rows: list[dict[str, object]], right_table: Table, right_name: str, on_expr: object
) -> list[dict[str, object]]:
    """Execute LEFT JOIN."""
    result = []
    for left_row in left_rows:
        found = False
        for right_row_data in right_table.rows:
            combined = left_row.copy()
            for i, col in enumerate(right_table.columns):
                combined[f"{right_name}.{col.name}"] = right_row_data[i]
                if col.name not in combined:
                    combined[col.name] = right_row_data[i]

            pred = evaluate(on_expr, combined)
            if pred is True:
                result.append(combined)
                found = True

        if not found:
            combined = left_row.copy()
            for col in right_table.columns:
                combined[f"{right_name}.{col.name}"] = None
                if col.name not in combined or col.name.startswith(right_name + "."):
                    combined[col.name] = None
            result.append(combined)
    return result


def _execute_where(stage: WhereStage, rows: list[dict[str, object]]) -> list[dict[str, object]]:
    """Execute WHERE clause."""
    result = []
    for row in rows:
        pred = evaluate(stage.expr, row)
        if pred is True:
            result.append(row)
    return result


def _execute_group_by(stage: GroupByStage, rows: list[dict[str, object]]) -> list[dict[str, object]]:
    """Execute GROUP BY clause."""
    if not stage.exprs:
        if rows:
            return [rows]
        return [[]]

    groups = {}
    group_order = []

    for row in rows:
        keys = tuple(evaluate(expr, row) for expr in stage.exprs)
        if keys not in groups:
            groups[keys] = []
            group_order.append(keys)
        groups[keys].append(row)

    return [groups[key] for key in group_order]


def _execute_having(stage: HavingStage, rows: list[list[dict[str, object]]]) -> list[list[dict[str, object]]]:
    """Execute HAVING clause."""
    result = []
    for group in rows:
        group_row = {}
        if group:
            for key in group[0].keys():
                group_row[key] = group[0][key]
        pred = evaluate(stage.expr, group_row)
        if pred is True:
            result.append(group)
    return result


def _execute_select(
    stage: SelectStage, rows: list[dict[str, object]] | list[list[dict[str, object]]],
    tables: dict[str, Table], plan: Plan
) -> tuple[list[list[object]], list[str]]:
    """Execute SELECT clause."""
    is_grouped = isinstance(rows[0], list) if rows else False

    if is_grouped:
        return _execute_select_grouped(stage, rows, tables)
    else:
        return _execute_select_ungrouped(stage, rows, tables)


def _execute_select_ungrouped(
    stage: SelectStage, rows: list[dict[str, object]], tables: dict[str, Table]
) -> tuple[list[list[object]], list[str]]:
    """Execute SELECT on ungrouped rows."""
    output_rows = []
    output_columns = []

    for row in rows:
        output_row = []
        if not output_columns:
            for item in stage.items:
                if item[0] is None and item[2]:
                    table_name = item[2]
                    if table_name not in tables:
                        raise UnknownTableError(f"Table '{table_name}' not found")
                    for col in tables[table_name].columns:
                        output_columns.append(col.name)
                elif item[0] is None:
                    raise ValueError("Invalid select item")
                else:
                    output_columns.append(item[1] or expr_to_string(item[0]))

        for item in stage.items:
            if item[0] is None and item[2]:
                table_name = item[2]
                for col in tables[table_name].columns:
                    output_row.append(row.get(f"{table_name}.{col.name}", None))
            elif item[0] is None:
                raise ValueError("Invalid select item")
            else:
                val = evaluate(item[0], row)
                output_row.append(val)

        output_rows.append(output_row)

    return output_rows, output_columns


def _execute_select_grouped(
    stage: SelectStage, groups: list[list[dict[str, object]]], tables: dict[str, Table]
) -> tuple[list[list[object]], list[str]]:
    """Execute SELECT on grouped rows."""
    output_rows = []
    output_columns = []

    for group in groups:
        output_row = []
        if not output_columns:
            for item in stage.items:
                if item[0] is None and item[2]:
                    table_name = item[2]
                    for col in tables[table_name].columns:
                        output_columns.append(col.name)
                elif item[0] is None:
                    raise ValueError("Invalid select item")
                else:
                    output_columns.append(item[1] or expr_to_string(item[0]))

        for item in stage.items:
            if item[0] is None and item[2]:
                table_name = item[2]
                for col in tables[table_name].columns:
                    output_row.append(group[0].get(f"{table_name}.{col.name}", None) if group else None)
            elif item[0] is None:
                raise ValueError("Invalid select item")
            elif is_aggregate_expr(item[0]):
                agg = Aggregator(item[0], group)
                output_row.append(agg.compute())
            else:
                val = evaluate(item[0], group[0]) if group else None
                output_row.append(val)

        output_rows.append(output_row)

    return output_rows, output_columns


def _execute_order_by(
    stage: OrderByStage, rows: list[list[object]], output_columns: list[str],
    tables: dict[str, Table], plan: Plan
) -> list[list[object]]:
    """Execute ORDER BY clause."""
    def sort_key(row_idx: int) -> tuple:
        row = rows[row_idx]
        keys = []
        for expr, direction in stage.items:
            try:
                val = evaluate(expr, {output_columns[i]: row[i] for i in range(len(output_columns))})
            except (KeyError, UnknownColumnError):
                for table in tables.values():
                    temp_row = {}
                    for i, r in enumerate(rows):
                        if i == row_idx:
                            for j, col in enumerate(table.columns):
                                temp_row[col.name] = r[j] if j < len(r) else None
                    try:
                        val = evaluate(expr, temp_row)
                        break
                    except:
                        pass
                else:
                    raise

            if val is None:
                keys.append((1, None))
            else:
                keys.append((0, val))
        return tuple(keys)

    sorted_indices = sorted(range(len(rows)), key=sort_key)
    result = []

    for idx in sorted_indices:
        result.append(rows[idx])

    return result


def _execute_distinct(rows: list[list[object]]) -> list[list[object]]:
    """Execute DISTINCT."""
    seen = set()
    result = []
    for row in rows:
        row_tuple = tuple(row)
        if row_tuple not in seen:
            seen.add(row_tuple)
            result.append(row)
    return result


def _execute_limit_offset(stage: LimitOffsetStage, rows: list[list[object]]) -> list[list[object]]:
    """Execute LIMIT and OFFSET."""
    offset = stage.offset or 0
    limit = stage.limit

    if limit is None:
        return rows[offset:]
    else:
        return rows[offset:offset+limit]

import sys
import csv
import io
from .schema import Table, Column
from . import execute
from .errors import MicroDBError


def main(argv: list[str] | None = None) -> int:
    """Main entry point for CLI."""
    if argv is None:
        argv = sys.argv[1:]

    if not argv:
        return 2

    tables = {}
    query = None
    i = 0

    while i < len(argv):
        if argv[i] == "--table" and i + 1 < len(argv):
            table_def = argv[i + 1]
            if "=" not in table_def:
                return 2
            name, path = table_def.split("=", 1)
            try:
                table = _load_csv(name, path)
                tables[name] = table
            except (FileNotFoundError, IOError):
                return 2
            except Exception:
                return 2
            i += 2
        else:
            query = argv[i]
            i += 1
            break

    if query is None:
        return 2

    if i < len(argv):
        return 2

    try:
        result = execute(query, tables)
        _write_csv(result)
        return 0
    except MicroDBError as e:
        sys.stderr.write(str(e) + "\n")
        return 3
    except Exception as e:
        sys.stderr.write(str(e) + "\n")
        return 3


def _load_csv(name: str, path: str) -> Table:
    """Load a CSV file as a table."""
    with open(path, "r") as f:
        reader = csv.reader(f)
        header = next(reader)

        columns = []
        for col_def in header:
            if ":" not in col_def:
                raise ValueError(f"Invalid column definition: {col_def}")
            col_name, col_type = col_def.split(":", 1)
            columns.append(Column(name=col_name, type=col_type))

        rows = []
        for row_data in reader:
            row = []
            for i, cell in enumerate(row_data):
                col_type = columns[i].type
                if not cell:
                    row.append(None)
                elif col_type == "INT":
                    row.append(int(cell))
                elif col_type == "FLOAT":
                    row.append(float(cell))
                elif col_type == "TEXT":
                    row.append(cell)
                elif col_type == "BOOL":
                    if cell.lower() == "true":
                        row.append(True)
                    elif cell.lower() == "false":
                        row.append(False)
                    else:
                        raise ValueError(f"Invalid BOOL value: {cell}")
                else:
                    raise ValueError(f"Unknown type: {col_type}")
            rows.append(row)

    return Table(name, columns, rows)


def _write_csv(result: object) -> None:
    """Write result as CSV to stdout."""
    buffer = io.StringIO()
    writer = csv.writer(buffer)

    writer.writerow(result.columns)

    for row in result.rows:
        output_row = []
        for cell in row:
            if cell is None:
                output_row.append("")
            elif isinstance(cell, bool):
                output_row.append("true" if cell else "false")
            else:
                output_row.append(str(cell))
        writer.writerow(output_row)

    sys.stdout.write(buffer.getvalue())


if __name__ == "__main__":
    sys.exit(main())

